// app/api/analysis/[id]/interview-probability/route.ts
// MOAT 9 — Interview Probability Engine™
//
// Combines: evidence strength (from EvidenceVault + this analysis),
// band level fit, essential criteria coverage, and historical shortlist
// performance (from past Applications) into a single Interview Probability score.
//
// This is NOT generated by AI writing quality — it's a calculated score
// from real evidence and historical data, with AI used only to interpret
// and explain the factors.

import { getDb }               from '@/lib/db-router'
import { getEffectiveUserId }  from '@/lib/effective-user'
import { prisma } from "@/lib/prisma"
import { auth } from "@/auth"
import { callGeminiJSON } from "@/lib/application/ai"

interface FactorScore {
  factor: string
  score: number        // 0-100
  weight: number       // contribution weight
  weightedScore: number
  explanation: string
}

function clamp(n: number, min = 0, max = 100) {
  return Math.max(min, Math.min(max, n))
}

export async function POST(req: Request, { params }: { params: Promise<{ id: string }> }) {
  try {
    const { id } = await params
    const session = await auth()
    if (!session?.user?.id) return Response.json({ error: "Unauthorized" }, { status: 401 })
    const userId = (await getEffectiveUserId()) ?? (session.user.id as string)
    const db     = await getDb(userId)

    const analysis = await db.analysis.findUnique({ where: { id } })
    if (!analysis || analysis.userId !== userId) {
      return Response.json({ error: "Not found" }, { status: 404 })
    }

    const result = (analysis.result as any) ?? {}

    // ─── FACTOR 1: Essential Criteria Coverage ──────────────────────────────
    const criteriaAnalysis = result.criteriaAnalysis ?? []
    const essential = criteriaAnalysis.filter((c: any) => c.type === "essential")
    const essentialMet = essential.filter((c: any) => c.status === "met").length
    const essentialPartial = essential.filter((c: any) => c.status === "partially met").length
    const criteriaCoverageScore = essential.length > 0
      ? clamp(((essentialMet * 1 + essentialPartial * 0.5) / essential.length) * 100)
      : 50

    // ─── FACTOR 2: Evidence Strength (from EvidenceVault) ───────────────────
    const evidenceEntries = await db.evidenceEntry.findMany({ where: { userId: userId } })
    const competencies = await db.competency.findMany({ where: { userId: userId } })

    const competentCount = competencies.filter(c => c.status === "competent").length
    const totalTrackedSkills = competencies.length || 1
    const competencyRatio = competentCount / totalTrackedSkills

    // Evidence depth: how many STAR entries exist with real content
    const substantialEvidence = evidenceEntries.filter(e =>
      e.situation.length > 50 && e.action.length > 50 && e.result.length > 30
    ).length

    // Evidence strength requires actual proof, not just self-marked competency status.
    // Competency ratio alone is a self-assessment; without STAR examples to back it up,
    // the score is capped low regardless of how many skills are marked "competent".
    let evidenceStrengthScore: number
    if (substantialEvidence === 0) {
      // No evidence at all — competency claims are unsubstantiated. Cap at 25.
      evidenceStrengthScore = clamp(competencyRatio * 25)
    } else {
      evidenceStrengthScore = clamp(
        (competencyRatio * 40) +                                  // competency ratio (max 40, requires evidence to fully count)
        (Math.min(substantialEvidence, 10) / 10 * 60)             // STAR evidence depth (max 60)
      )
    }

    // ─── FACTOR 3: Band Level Fit ───────────────────────────────────────────
    // Use scoredBreakdown if present (from Band Match DNA), else fall back to overall score
    const scored = result.scoredBreakdown ?? {}
    const overallScore = result.overallScore ?? scored.overallScore ?? 60
    const bandFitScore = clamp(overallScore)

    // ─── FACTOR 4: Historical Shortlist Performance ─────────────────────────
    const pastApplications = await db.application.findMany({
      where: { userId: userId },
      select: { status: true, createdAt: true },
    })

    let historicalScore = 40 // conservative default — no track record to draw on yet
    let historicalNote = "Not enough application history yet to assess a track record — scored conservatively until you build one."
    const total = pastApplications.length

    if (total >= 2) {
      const completed = pastApplications.filter(a => a.status === "complete").length
      const completionRate = completed / total
      historicalScore = clamp(40 + completionRate * 40)
      historicalNote = `Based on ${total} application${total === 1 ? '' : 's'} started, ${completed} completed to a finished statement.`
    } else if (total === 1) {
      historicalScore = 45
      historicalNote = "Only one application on record so far — not enough history to assess a track record yet."
    }

    // ─── Weighted combination ────────────────────────────────────────────────
    const factors: FactorScore[] = [
      {
        factor: "Essential Criteria Coverage",
        score: Math.round(criteriaCoverageScore),
        weight: 0.35,
        weightedScore: Math.round(criteriaCoverageScore * 0.35),
        explanation: `${essentialMet} of ${essential.length} essential criteria fully met${essentialPartial > 0 ? `, ${essentialPartial} partially met` : ''}.`,
      },
      {
        factor: "Evidence Strength",
        score: Math.round(evidenceStrengthScore),
        weight: 0.30,
        weightedScore: Math.round(evidenceStrengthScore * 0.30),
        explanation: substantialEvidence === 0
          ? `${competentCount}/${totalTrackedSkills} skills marked competent, but with 0 STAR examples in EvidenceVault™ to support these claims — scored as unsubstantiated.`
          : `${competentCount}/${totalTrackedSkills} skills signed off as competent, ${substantialEvidence} detailed STAR examples in EvidenceVault™.`,
      },
      {
        factor: "Band Level Fit",
        score: Math.round(bandFitScore),
        weight: 0.20,
        weightedScore: Math.round(bandFitScore * 0.20),
        explanation: `Overall application score of ${Math.round(overallScore)}% against this role's requirements.`,
      },
      {
        factor: "Application Track Record",
        score: Math.round(historicalScore),
        weight: 0.15,
        weightedScore: Math.round(historicalScore * 0.15),
        explanation: historicalNote,
      },
    ]

    const interviewProbability = clamp(Math.round(factors.reduce((sum, f) => sum + f.weightedScore, 0)))

    // ─── Explicit arithmetic — so the candidate can verify the total themselves ──
    const calculationLines = factors.map(f =>
      `${f.factor}: ${f.score} × ${Math.round(f.weight * 100)}% = ${f.weightedScore}`
    )
    calculationLines.push(`Total: ${factors.map(f => f.weightedScore).join(' + ')} = ${interviewProbability}`)

    // ─── AI interpretation — explain in plain English + give 3 actions ──────
    const prompt = `
You are an NHS recruitment analyst. A candidate has an Interview Probability score of ${interviewProbability}%.

This score is calculated (not AI-generated) from these weighted factors:
${factors.map(f => `- ${f.factor}: ${f.score}/100 (weight ${Math.round(f.weight * 100)}%) — ${f.explanation}`).join("\n")}

Job: ${analysis.jobTitle}
Band: ${(analysis as any).band ?? "Not specified"}

Provide:
1. A one-sentence plain-English summary of what this score means for this candidate
2. The single biggest factor holding the score back
3. Three specific, actionable steps to improve the score — ranked by impact

Respond ONLY with JSON:
{
  "summary": "one sentence",
  "biggestBlocker": "the factor and why",
  "actions": [
    { "action": "specific action", "impact": "high|medium|low", "factor": "which factor this improves" }
  ]
}
`.trim()

    let interpretation: any = {}
    try {
      interpretation = await callGeminiJSON(prompt, 1000)
    } catch (e) {
      interpretation = {
        summary: `An interview probability of ${interviewProbability}% based on your current evidence and criteria coverage.`,
        biggestBlocker: factors.sort((a, b) => a.score - b.score)[0]?.factor ?? "Evidence Strength",
        actions: [],
      }
    }

    const responseData = {
      success: true,
      interviewProbability,
      band: interviewProbability >= 70 ? "high" : interviewProbability >= 45 ? "moderate" : "low",
      factors,
      calculationLines,
      summary: interpretation.summary ?? "",
      biggestBlocker: interpretation.biggestBlocker ?? "",
      actions: interpretation.actions ?? [],
      updatedAt: new Date().toISOString(),
    }

    // Save — guarded in case schema migration hasn't run yet
    try {
      // @ts-expect-error — requires interviewProbability Json? on Analysis model
      await db.analysis.update({ where: { id }, data: { interviewProbability: responseData } })
    } catch (saveErr) {
      console.warn("[Interview Probability] Save skipped — run prisma db push:", (saveErr as any)?.message)
    }

    return Response.json(responseData)
  } catch (error: any) {
    console.error("INTERVIEW_PROBABILITY_ERROR:", error)
    return Response.json({ error: error?.message ?? "Failed" }, { status: 500 })
  }
}

export async function GET(req: Request, { params }: { params: Promise<{ id: string }> }) {
  try {
    const { id } = await params
    const session = await auth()
    if (!session?.user?.id) return Response.json({ error: "Unauthorized" }, { status: 401 })
    const userId = (await getEffectiveUserId()) ?? (session.user.id as string)
    const db     = await getDb(userId)

    const analysis = await db.analysis.findUnique({ where: { id } })
    if (!analysis || analysis.userId !== userId) {
      return Response.json({ error: "Not found" }, { status: 404 })
    }

    try {
      return Response.json({ success: true, data: analysis.interviewProbability ?? null })
    } catch {
      return Response.json({ success: true, data: null })
    }
  } catch (error: any) {
    return Response.json({ error: error?.message ?? "Failed" }, { status: 500 })
  }
}